direction=#{q.direction}
AND partner_id=#{q.partnerId}
AND settle_month=#{q.period}
AND reconcile_status=#{q.status}
AND basis_ready=0
AND settled_amount < gross_amount
AND due_date < CURRENT_DATE AND settled_amount < gross_amount
AND (LOCATE(#{q.keyword},partner_name)>0 OR LOCATE(#{q.keyword},source_no)>0 OR LOCATE(#{q.keyword},order_no)>0 OR LOCATE(#{q.keyword},COALESCE(partner_order_no,''))>0 OR LOCATE(#{q.keyword},part_no)>0)

mapper.select:
SELECT 'AP' direction,'INBOUND' source_type,a.id source_line_id,h.id source_id,h.inbound_order_no source_no, a.purchase_order_id order_id,a.purchase_order_no order_no,NULL partner_order_no, h.supplier_id partner_id,h.supplier_name partner_name,i.product_id,i.brand,i.part_no,i.package_type, a.allocated_quantity quantity,a.unit_price,a.tax_included,a.tax_rate,a.amount gross_amount,a.currency, DATE(h.inbound_time) biz_date,DATE(h.inbound_time) basis_date,1 basis_ready FROM inbound_order_item_alloc a JOIN inbound_order h ON h.id=a.inbound_order_id JOIN inbound_order_item i ON i.id=a.inbound_order_item_id WHERE h.status='COMPLETED' AND h.id=#{sourceId}
SELECT 'AR' direction,'OUTBOUND' source_type,a.id source_line_id,h.id source_id,h.outbound_order_no source_no, a.sales_order_id order_id,a.sales_order_no order_no,a.customer_order_no partner_order_no, h.customer_id partner_id,h.customer_name partner_name,i.product_id,i.brand,i.part_no,i.package_type, a.allocated_quantity quantity,a.unit_price,a.tax_included,a.tax_rate,a.amount gross_amount,a.currency, DATE(h.outbound_time) biz_date,DATE(h.sign_time) basis_date,IF(h.sign_time IS NULL,0,1) basis_ready FROM outbound_order_item_alloc a JOIN outbound_order h ON h.id=a.outbound_order_id JOIN outbound_order_item i ON i.id=a.outbound_order_item_id WHERE h.status='COMPLETED' AND h.id=#{sourceId}
ORDER BY a.id

mapper.update:
UPDATE fin_open_item SET basis_date=#{basisDate},basis_ready=#{basisReady},period=#{period},
  period_start=#{periodStart},period_end=#{periodEnd},settle_month=#{settleMonth},due_date=#{dueDate}
WHERE id=#{id} AND statement_id IS NULL AND reconcile_status='OPEN'
